//! The page client: a shell and content-hashed files compiled into the binary, so a package built
//! from the source archive serves the page without node. `assets/table.rs` is generated by
//! `scripts/generate-stats-assets.sh` from `crates/oxiroute-server/assets/stats`.

use std::path::Path;

use crate::{ApiResponse, rtmp::api::response::matches_validator};

#[rustfmt::skip]
mod table;

/// Every file below `assets/` carries a content hash in its name, so a URL never changes meaning.
const IMMUTABLE: &str = "public, max-age=31536000, immutable";

pub(super) struct Asset {
    pub(super) name: &'static str,
    pub(super) etag: &'static str,
    pub(super) body: &'static [u8],
}

pub(super) fn all() -> &'static [Asset] {
    table::ASSETS
}

/// The shell template; `html::render` fills in the prefix, the refresh interval and the table.
pub(super) fn shell() -> &'static str {
    table::SHELL
}

/// `name` is exactly one file name: the table is the only source, so no path can reach anything else.
pub(super) fn response(name: &str, if_none_match: Option<&str>) -> ApiResponse {
    let Some(asset) = all().iter().find(|asset| asset.name == name) else {
        return ApiResponse::route_not_found();
    };
    if if_none_match.is_some_and(|header| matches_validator(header, asset.etag)) {
        return ApiResponse::not_modified(asset.etag.to_owned()).with_cache_control(IMMUTABLE);
    }
    ApiResponse::bytes(200, asset.body.to_vec(), content_type(name))
        .with_etag(asset.etag.to_owned())
        .with_cache_control(IMMUTABLE)
}

pub(super) fn content_type(name: &str) -> &'static str {
    match Path::new(name)
        .extension()
        .and_then(|extension| extension.to_str())
    {
        Some("js") => "text/javascript; charset=utf-8",
        Some("css") => "text/css; charset=utf-8",
        Some("svg") => "image/svg+xml",
        Some("png") => "image/png",
        Some("ico") => "image/x-icon",
        Some("woff2") => "font/woff2",
        _ => "application/octet-stream",
    }
}
